// TH16 v1.00a Stage 6 MainSub00 (st06.ecl.txt:632-658)
// Two rings of ten ECir00 (st06.ecl.txt:4-40). Each ECir00 fires single aimed
// shots through ECir00_at (95-144) and owns the ECir00DeadAttack1/Et1 death
// burst (42-93).
const TIME_LIMIT: int = 960;
const OPENING_BUFFER: int = 120;

const TH16_RING_BALL: int = 448; // source type 6 (etSprite(0,6,6))
const TH16_RICE: int = 480;      // source type 8 (etSprite(0,8,6))
const COLOR_TH16: int = 6;       // source color 6 for both types

// Source ECir00DeadAttackEt1 writes EX records ANIM(a=1) then WAIT(90/90/40/20).
// The birth ANIM stage is omitted (approved); its 4*velocity spawn retreat is
// applied at the fire site. The trailing WAIT only stalls an EX cursor that has
// no further record, so it is reproduced here for fidelity and changes nothing.
xformdef DEATH_TRAIL(frames: int) {
    wait(frames);
}

// ECir00DeadAttack1 -> ECir00DeadAttackEt1: one fixed ring burst at the dying
// enemy's position (enmCreate 0,0 relative to parent FINAL = that position).
// aim mode 3, base angle = ANGLE_PLAYER read once, N=1..16 per rank, speed 1.2.
sub ecir00_death_burst() {
    var count: int = 1;
    var trail: int = 90;
    var rank: int = global(GVAR_RANK);
    if rank == RANK_NORMAL { count = 8; }
    if rank == RANK_HARD { count = 12; trail = 40; }
    if rank == RANK_LUNATIC { count = 16; trail = 20; }
    var base: angle = aim_player();
    var n: int = 0;
    while n < count {
        // Source ring alpha + (i*2pi/N); remainder spread like (i*65536)/N.
        var a: angle = base + ((n * 65536) / count) as angle;
        // ANIM a=1: position -= 4*velocity (speed 1.2 along own angle).
        _ = fire(TH16_RING_BALL, COLOR_TH16,
                 $self_x - 4.8fx * cos(a), $self_y - 4.8fx * sin(a),
                 1.2fx, a, DEATH_TRAIL(trail), none);
        n = n + 1;
    }
}

// 556 setDeath("ECir00DeadAttack1") armed at t=60; the callback is a real HP
// death path. The training shell keeps this enemy invulnerable, so it does not
// fire there, but the behavior is kept rather than dropped.
async sub ecir00_death_watch() {
    loop {
        if $self_hp <= 0 {
            ecir00_death_burst();
            die();
        }
        wait(1);
    }
}

// ECir00_at (st06.ecl.txt:95-144): 20 single aimed shots, one per period.
async sub ecir00_at() {
    wait(10);
    var amp: int = 182;      // Easy: RANDF2 * 0.017453292 rad (1 deg)
    var speed: fx = 1fx;     // Easy: etSpeed first value
    var gap: int = 30;
    var rank: int = global(GVAR_RANK);
    if rank != RANK_EASY {
        amp = 5461;          // Normal/Hard/Lunatic: RANDF2 * 0.5235988 rad (30 deg)
        speed = 3fx;
        if rank == RANK_HARD { gap = 20; }
        if rank == RANK_LUNATIC { gap = 15; }
    }
    for i in 0..20 {
        // Source %ANGLE_PLAYER + RANDF2*amp, sampled once per shot at etOn time.
        var jitter: int = (rand(65536) - 32768) * amp / 32768;
        var a: angle = aim_player() + (jitter as angle);
        // ANIM a=1 retreat: position -= 4*velocity, velocity = speed along a.
        _ = fire(TH16_RICE, COLOR_TH16,
                 $self_x - 4fx * speed * cos(a), $self_y - 4fx * speed * sin(a),
                 speed, a, none, none);
        wait(gap);
    }
}

// ECir00 (st06.ecl.txt:4-40). dir is the parent %F2 snapshot taken at
// enmCreate time.
async sub ecir00(dir: angle) {
    set_invuln(65535);
    set_hurtbox(12fx);               // 500 setHurtbox(24,24) -> r=12
    set_hitbox(8fx);                 // 501 setHitbox(16,16) -> r=8
    set_enemy_flag(ENEMY_NO_BODY, 1); // 502 flagSet(15): 0x2 body gate for 60f
    move_vel(0, dir, 0fx, EASE_LINEAR);          // 404 moveVel(dir,0)
    move_vel(60, dir, 1fx, EASE_QUAD_IN);        // 405 mode1
    wait(60);
    // 503 flagClear(15) re-enables body contact (0x4/0x8 offscreen-skip ends
    // here too; the enemy is still on screen at this point).
    set_enemy_flag(ENEMY_NO_BODY, 0);
    spawn ecir00_at();            // 0030 @ECir00_at() async
    spawn ecir00_death_watch();   // 0026 setDeath + 0060-0092 death burst
    wait(60);
    move_vel(0, dir, 0fx, EASE_LINEAR);          // 404 moveVel(dir,0)
    move_speed(120, 2fx, EASE_QUAD_IN);          // 445 mode1
    loop { wait(1000); }                         // 0035-0038
}

// MainSub00 body. enmCreate is relative to the stage task's FINAL (0,0), so the
// spawn point is world (0,224).
async sub pattern() {
    wait(OPENING_BUFFER);
    wait(120);                       // 0635 wait(120)
    var f2: angle = 0deg;            // 0638 %F2 = 0.0f
    for i in 0..10 {                 // 0639-0646 $E=10 first group
        _ = spawn_enemy(0fx, 224fx, 250, 0, 0, 0, ecir00(f2));
        f2 = f2 - 20deg;             // 0643 -0.349066
        wait(2);
    }
    wait(200);                       // 0647
    f2 = 180deg;                     // 0648 3.141593
    for j in 0..10 {                 // 0649-0656 $F=10 second group
        _ = spawn_enemy(0fx, 224fx, 250, 0, 0, 0, ecir00(f2));
        f2 = f2 + 20deg;             // 0653 +0.349066
        wait(2);
    }
    // Remaining tail: last enemy leaves the field (engine offscreen cleanup)
    // around card frame 935 in both ranks.
    wait(460);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
